"""The committed generated files match what the generator produces now."""

from tools.gen import ROOT, generate


def test_generated_files_are_up_to_date() -> None:
    stale = [
        str(path.relative_to(ROOT))
        for path, text in generate().items()
        if not path.exists() or path.read_text() != text
    ]
    assert not stale, f"run `uv run python -m tools.gen`; stale: {stale}"


def test_generated_files_carry_the_header() -> None:
    for path in generate():
        assert path.read_text().startswith("# Code generated by tools/gen. DO NOT EDIT.\n")
